147	func TestParse_DuplicateNamesComparedAfterDecoding(t *testing.T) {
148		base := `"app":"a","revision":"r","image":"i","batchSize":1`
149		// Equivalent Unicode escape spellings are the same name.
150		body := `{"id":"x","tags":{"env":"prod","env":"dev"}}`
151		err := parseDupErr(t, `{`+base+`,"clusters":[`+body+`]}`)
152		if !strings.Contains(err.Error(), `"env"`) {
153			t.Fatalf("expected decoded field name \"env\" in %q", err)
154		}
155	
156		// Case differences are different names.
157		valid := `{` + base + `,"clusters":[{"id":"x","tags":{"env":"prod","ENV":"dev"}}]}`
158		if _, err := ParseReleaseInput([]byte(valid)); err != nil {
159			t.Fatalf("case-different names must not be duplicates: %v", err)
160		}
161		// Spacing differences are different names (no trimming).
162		valid = `{` + base + `,"clusters":[{"id":"x","tags":{" env":"prod","env":"dev"}}]}`
163		if _, err := ParseReleaseInput([]byte(valid)); err != nil {
164			t.Fatalf("spacing-different names must not be duplicates: %v", err)
165		}
166	}
