231	func TestParse_DuplicateBeatsBusinessErrors(t *testing.T) {
232		// Duplicate member plus missing app: duplicate error must come first.
233		doc := `{"revision":"r","image":"i","batchSize":1,"clusters":[` +
234			`{"id":"a","disabled":true,"disabled":false}]}`
235		err := parseDupErr(t, doc)
236		if !strings.Contains(err.Error(), "disabled") {
237			t.Fatalf("expected duplicate error before business error, got %q", err)
238		}
239	
240		// Duplicate plus empty tag key: duplicate wins.
241		doc = `{"app":"a","revision":"r","image":"i","batchSize":1,"clusters":[` +
242			`{"id":"a","tags":{"env":1,"env":2,"":3}}]}`
243		err = parseDupErr(t, doc)
244		if !strings.Contains(err.Error(), "env") {
245			t.Fatalf("expected duplicate error before tag-key error, got %q", err)
246		}
247	
248		// With no duplicate, business errors are still reported as before.
249		doc = `{"revision":"r","image":"i","batchSize":1,"clusters":[]}`
250		if _, err := ParseReleaseInput([]byte(doc)); err == nil ||
251			!strings.Contains(err.Error(), "app") {
252			t.Fatalf("expected missing app error, got %v", err)
253		}
254	}
