256	func TestParse_ValidConfigsStillPlan(t *testing.T) {
257		raw := `{
258			"app": "payments", "revision": "v1.2.3", "image": "reg/payments:v1.2.3",
259			"batchSize": 2,
260			"clusters": [
261				{"id": "c3", "tags": {"env": "prod"}},
262				{"id": "c1", "tags": {"env": "dev"}},
263				{"id": "c2", "disabled": true, "tags": {"env": "prod"}},
264				{"id": "c4", "tags": {"env": "prod", "region": "us"}}
265			],
266			"include": [{"env": "prod"}],
267			"exclude": [{"region": "us"}]
268		}`
269		in, err := ParseReleaseInput([]byte(raw))
270		if err != nil {
271			t.Fatal(err)
272		}
273		plan, err := MakeReleasePlan(in)
274		if err != nil {
275			t.Fatal(err)
276		}
277		// c1 is dev -> include-not-matched; c2 disabled; c4 prod+us -> excluded;
278		// c3 selected.
279		if len(plan.Batches) != 1 || strings.Join(plan.Batches[0].Clusters, ",") != "c3" {
280			t.Fatalf("unexpected plan: %+v", plan.Batches)
281		}
282		if len(plan.Excluded) != 3 {
283			t.Fatalf("expected 3 excluded, got %+v", plan.Excluded)
284		}
285	}
