package darksafe

import "testing"

func TestScratchEscapeBehavior(t *testing.T) {
	base := `"app":"a","revision":"r","image":"i","batchSize":1`
	cases := []string{
		// direct vs partially escaped
		`{` + base + `,"clusters":[{"id":"x","tags":{"env":"prod","env":"dev"}}]}`,
		// all escaped vs direct (escaped first)
		`{` + base + `,"clusters":[{"id":"x","tags":{"env":1,"env":2}}]}`,
		// direct first, escaped second
		`{` + base + `,"clusters":[{"id":"x","tags":{"env":1,"env":2}}]}`,
		// non-BMP direct vs surrogate pair
		`{` + base + `,"clusters":[{"id":"x","tags":{"😀":1,"😀":2}}]}`,
		// top-level app direct vs escaped
		`{"app":"a","app":"b","revision":"r","image":"i","batchSize":1,"clusters":[]}`,
		// unknown nested field
		`{` + base + `,"clusters":[],"meta":{"x":1,"x":2}}`,
		// file order: second z appears before second a
		`{` + base + `,"clusters":[],"meta":{"z":1,"z":2,"a":3,"a":4}}`,
		// array index preserved
		`{` + base + `,"clusters":[],"items":[{"k":1},{"y":1,"y":2}]}`,
	}
	for i, c := range cases {
		_, err := ParseReleaseInput([]byte(c))
		t.Logf("case %d err = %v", i, err)
	}
	// valid distinctions
	valid := []string{
		`{` + base + `,"clusters":[{"id":"x","tags":{"env":"prod","ENV":"dev"}}]}`,
		`{` + base + `,"clusters":[{"id":"x","tags":{"env":"prod"," env":"dev"}}]}`,
		`{` + base + `,"clusters":[{"id":"a","tags":{"env":"prod"}},{"id":"b","tags":{"env":"dev"}}]}`,
	}
	for i, c := range valid {
		if _, err := ParseReleaseInput([]byte(c)); err != nil {
			t.Errorf("valid case %d unexpectedly rejected: %v", i, err)
		}
	}
}

