package darksafe

import (
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

// These tests guard the rule that duplicate JSON object members are detected
// by their names *after JSON string decoding*: a member written directly
// ("env") and one written via Unicode escapes ("env") are the same
// member, including non-BMP characters written as surrogate pairs. The
// production check already walks decoded tokens (checkDuplicateMembers in
// plan.go); these cases make sure that behavior cannot regress.
//
// Shared configuration prefix; escape spellings only ever appear inside member
// names, never in values, so each case isolates the name-decoding rule.
const escapedDupBase = `"app":"a","revision":"r","image":"i","batchSize":1`

// TestParse_EscapedDuplicateMemberNames documents that two member names which
// differ only in how their characters are escaped are duplicates once decoded,
// and that the error names the decoded name and the object's position.
func TestParse_EscapedDuplicateMemberNames(t *testing.T) {
	cases := []struct {
		name      string
		body      string // JSON body without outer braces
		wantField string
		wantPath  string
	}{
		{
			name:      "top-level direct first then escaped",
			body:      `"app":"a","app":"b","revision":"r","image":"i","batchSize":1,"clusters":[]`,
			wantField: "app",
			wantPath:  "$",
		},
		{
			name:      "top-level escaped first then direct",
			body:      `"app":"a","app":"b","revision":"r","image":"i","batchSize":1,"clusters":[]`,
			wantField: "app",
			wantPath:  "$",
		},
		{
			name:      "cluster tags direct then escaped",
			body:      escapedDupBase + `,"clusters":[{"id":"x","tags":{"env":"prod","env":"dev"}}]`,
			wantField: "env",
			wantPath:  "$.clusters[0].tags",
		},
		{
			name:      "cluster tags escaped then direct",
			body:      escapedDupBase + `,"clusters":[{"id":"x","tags":{"env":"prod","env":"dev"}}]`,
			wantField: "env",
			wantPath:  "$.clusters[0].tags",
		},
		{
			name:      "cluster tags both fully escaped",
			body:      escapedDupBase + `,"clusters":[{"id":"x","tags":{"env":"prod","env":"dev"}}]`,
			wantField: "env",
			wantPath:  "$.clusters[0].tags",
		},
		{
			name:      "cluster tags mixed escapes at different positions",
			body:      escapedDupBase + `,"clusters":[{"id":"x","tags":{"env":"prod","env":"dev"}}]`,
			wantField: "env",
			wantPath:  "$.clusters[0].tags",
		},
		{
			name:      "include condition direct and escaped",
			body:      escapedDupBase + `,"clusters":[],"include":[{"env":"prod","env":"dev"}]`,
			wantField: "env",
			wantPath:  "$.include[0]",
		},
		{
			name:      "exclude condition direct and escaped",
			body:      escapedDupBase + `,"clusters":[],"exclude":[{"region":"us","region":"eu"}]`,
			wantField: "region",
			wantPath:  "$.exclude[0]",
		},
		{
			name:      "cluster object own member id",
			body:      escapedDupBase + `,"clusters":[{"id":"a","id":"b"}]`,
			wantField: "id",
			wantPath:  "$.clusters[0]",
		},
		{
			name:      "unknown extra field nested object",
			body:      escapedDupBase + `,"clusters":[],"meta":{"x":1,"x":2}`,
			wantField: "x",
			wantPath:  "$.meta",
		},
		{
			name:      "unknown extra field object nested inside array",
			body:      escapedDupBase + `,"clusters":[],"items":[{"y":1,"y":2}]`,
			wantField: "y",
			wantPath:  "$.items[0]",
		},
		{
			name:      "escaped name equal after decoding different escape of same rune",
			body:      escapedDupBase + `,"clusters":[],"meta":{"é":1,"é":2}`,
			wantField: "é",
			wantPath:  "$.meta",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			err := parseDupErr(t, "{"+tc.body+"}")
			msg := err.Error()
			if !strings.Contains(msg, tc.wantField) {
				t.Fatalf("error %q does not name decoded field %q", msg, tc.wantField)
			}
			if !strings.Contains(msg, tc.wantPath) {
				t.Fatalf("error %q does not contain path %q", msg, tc.wantPath)
			}
		})
	}
}

// TestParse_EscapedSurrogatePairDuplicate covers a name with a legal
// supplementary-plane (non-BMP) character: written directly it must be the
// same name as a pair of UTF-16 surrogate escapes, in either order.
func TestParse_EscapedSurrogatePairDuplicate(t *testing.T) {
	// U+1F600 (😀): direct vs. "😀" surrogate pair.
	docs := []string{
		`{` + escapedDupBase + `,"clusters":[{"id":"x","tags":{"😀":1,"😀":2}}]}`,
		`{` + escapedDupBase + `,"clusters":[{"id":"x","tags":{"😀":1,"😀":2}}]}`,
		`{` + escapedDupBase + `,"clusters":[{"id":"x","tags":{"😀":1,"😀":2}}]}`,
	}
	for i, doc := range docs {
		err := parseDupErr(t, doc)
		msg := err.Error()
		if !strings.Contains(msg, "😀") {
			t.Fatalf("case %d: error should show decoded non-BMP name, got %q", i, msg)
		}
		if !strings.Contains(msg, "$.clusters[0].tags") {
			t.Fatalf("case %d: error should locate tags object, got %q", i, msg)
		}
	}

	// The same check applies to a top-level member and an unknown field.
	err := parseDupErr(t, `{"app":"a","appp":"b","revision":"r","image":"i","batchSize":1,"clusters":[]}`)
	if !strings.Contains(err.Error(), `"app"`) || !strings.Contains(err.Error(), "$") {
		t.Fatalf("top-level escaped duplicate not reported: %v", err)
	}
	err = parseDupErr(t, `{`+escapedDupBase+`,"clusters":[],"meta":{"😀":1,"😀":2}}`)
	if !strings.Contains(err.Error(), "😀") || !strings.Contains(err.Error(), "$.meta") {
		t.Fatalf("unknown-field non-BMP duplicate not reported: %v", err)
	}
}

// TestParse_EscapedDuplicateRejectedForAllValuePairs mirrors the literal
// value-pair rule using differently-spelled names: equal values, different
// values, and different value types must all reject the whole configuration.
func TestParse_EscapedDuplicateRejectedForAllValuePairs(t *testing.T) {
	// Same value under both spellings.
	for _, val := range []string{`true`, `false`, `null`, `1`, `1.5`, `"str"`, `[1,2]`, `{"k":"v"}`} {
		t.Run("same value "+val, func(t *testing.T) {
			doc := `{` + escapedDupBase + `,"clusters":[` +
				`{"id":"x","tags":{"env":` + val + `,"env":` + val + `}}]}`
			err := parseDupErr(t, doc)
			if !strings.Contains(err.Error(), `"env"`) ||
				!strings.Contains(err.Error(), "$.clusters[0].tags") {
				t.Fatalf("escaped-name same-value pair must be rejected, got %q", err)
			}
		})
	}
	// Different values and different value types.
	pairs := [][2]string{
		{`"prod"`, `"dev"`},
		{`1`, `2`},
		{`1`, `true`},
		{`"a"`, `null`},
		{`[]`, `{}`},
		{`false`, `"false"`},
	}
	for _, p := range pairs {
		t.Run("values "+p[0]+" "+p[1], func(t *testing.T) {
			doc := `{` + escapedDupBase + `,"clusters":[` +
				`{"id":"x","tags":{"env":` + p[0] + `,"env":` + p[1] + `}}]}`
			err := parseDupErr(t, doc)
			if !strings.Contains(err.Error(), `"env"`) {
				t.Fatalf("escaped-name pair must be rejected regardless of values, got %q", err)
			}
		})
	}
}

// TestParse_EscapedDuplicateArrayIndexAndFileOrder checks that the decoded
// duplicate inside an object nested in an array keeps the actual array index,
// and that when several duplicates exist the earliest second occurrence in the
// file is reported — not a name-sorted choice.
func TestParse_EscapedDuplicateArrayIndexAndFileOrder(t *testing.T) {
	// Object at index 1 of an unknown-field array.
	err := parseDupErr(t, `{`+escapedDupBase+`,"clusters":[],"items":[{"ok":1},{"y":1,"y":2}]}`)
	if !strings.Contains(err.Error(), `"y"`) || !strings.Contains(err.Error(), "$.items[1]") {
		t.Fatalf("expected duplicate at $.items[1], got %q", err)
	}

	// Second cluster object, escaped duplicate of its own member.
	err = parseDupErr(t, `{`+escapedDupBase+`,"clusters":[{"id":"a"},{"id":"b","id":"c"}]}`)
	if !strings.Contains(err.Error(), `"id"`) || !strings.Contains(err.Error(), "$.clusters[1]") {
		t.Fatalf("expected duplicate at $.clusters[1], got %q", err)
	}

	// Two decoded duplicates: "z" sorts after "a", but z's second occurrence
	// appears earlier in the file, so z must be reported.
	err = parseDupErr(t, `{`+escapedDupBase+`,"clusters":[],"meta":{`+
		`"z":1,"z":2,"a":3,"a":4}}`)
	if !strings.Contains(err.Error(), `"z"`) || !strings.Contains(err.Error(), "$.meta") {
		t.Fatalf("expected earliest second occurrence (z), got %q", err)
	}

	// Earlier object beats a later object regardless of names.
	err = parseDupErr(t, `{`+escapedDupBase+`,"clusters":[`+
		`{"id":"a","tags":{"zzz":1,"zzz":2}},`+
		`{"id":"b","tags":{"aaa":1,"aaa":2}}]}`)
	if !strings.Contains(err.Error(), "zzz") || !strings.Contains(err.Error(), "$.clusters[0].tags") {
		t.Fatalf("expected clusters[0] duplicate first in file order, got %q", err)
	}
}

// TestParse_EscapedDuplicateBeatsBusinessValidation ensures a decoded
// duplicate is reported before business-field validation — even when the
// configuration also lacks a required application name.
func TestParse_EscapedDuplicateBeatsBusinessValidation(t *testing.T) {
	// Missing "app" plus an escaped duplicate: duplicate must win.
	doc := `{"revision":"r","image":"i","batchSize":1,"clusters":[` +
		`{"id":"a","disabled":true,"disabled":false}]}`
	err := parseDupErr(t, doc)
	msg := err.Error()
	if !strings.Contains(msg, `"disabled"`) || !strings.Contains(msg, "$.clusters[0]") {
		t.Fatalf("expected escaped duplicate before missing-app error, got %q", msg)
	}

	// Escaped duplicate in tags plus an empty tag key: duplicate wins.
	doc = `{"app":"a","revision":"r","image":"i","batchSize":1,"clusters":[` +
		`{"id":"a","tags":{"env":1,"env":2,"":3}}]}`
	err = parseDupErr(t, doc)
	if !strings.Contains(err.Error(), `"env"`) {
		t.Fatalf("expected escaped duplicate before empty-key error, got %q", err)
	}

	// Escaped duplicate in an unknown field plus missing app: still duplicate.
	doc = `{"revision":"r","image":"i","batchSize":1,"clusters":[],` +
		`"meta":{"x":1,"x":2}}`
	err = parseDupErr(t, doc)
	if !strings.Contains(err.Error(), `"x"`) || !strings.Contains(err.Error(), "$.meta") {
		t.Fatalf("expected unknown-field duplicate before business error, got %q", err)
	}
}

// TestParse_EscapedNamesThatDecodeDifferentlyAreDistinct guards legitimate
// inputs: comparison is exact equality of the decoded strings, with no case
// folding, trimming, or unification across separate objects.
func TestParse_EscapedNamesThatDecodeDifferentlyAreDistinct(t *testing.T) {
	valid := []struct {
		name string
		body string
	}{
		{
			name: "case differs after decoding",
			body: escapedDupBase + `,"clusters":[{"id":"x","tags":{"env":"prod","ENV":"dev"}}]`,
		},
		{
			name: "leading space vs no space",
			body: escapedDupBase + `,"clusters":[{"id":"x","tags":{" env":"prod","env":"dev"}}]`,
		},
		{
			name: "escape vs escape decoding to different rune",
			body: escapedDupBase + `,"clusters":[{"id":"x","tags":{"é":1,"e":2}}]`,
		},
		{
			name: "same tag key on two different clusters",
			body: escapedDupBase + `,"clusters":[` +
				`{"id":"a","tags":{"env":"prod"}},` +
				`{"id":"b","tags":{"env":"dev"}}]}`,
		},
		{
			name: "same key in parent and nested unknown objects",
			body: escapedDupBase + `,"clusters":[],"meta":{"env":"x","nested":{"env":"y"}}}`,
		},
		{
			name: "same key in two include conditions",
			body: escapedDupBase + `,"clusters":[],"include":[{"env":"prod"},{"env":"dev"}]}`,
		},
		{
			name: "non-BMP name vs BMP name that merely look related",
			body: escapedDupBase + `,"clusters":[{"id":"x","tags":{"😀":1,"\uDE00":2}}]}`,
		},
	}
	for _, tc := range valid {
		t.Run(tc.name, func(t *testing.T) {
			if _, err := ParseReleaseInput([]byte("{" + tc.body + "}")); err != nil {
				t.Fatalf("distinct decoded names must not be duplicates: %v", err)
			}
		})
	}
}

// TestParse_EscapedNamesProduceEquivalentPlans checks that escaped and direct
// spellings of the same member names express identical content: app info,
// cluster selection, batch arrangement, and non-selection reasons must match
// between the two documents.
func TestParse_EscapedNamesProduceEquivalentPlans(t *testing.T) {
	direct := `{
		"app": "payments", "revision": "v1.2.3", "image": "reg/payments:v1.2.3",
		"batchSize": 2,
		"clusters": [
			{"id": "c3", "tags": {"env": "prod"}},
			{"id": "c1", "tags": {"env": "dev"}},
			{"id": "c2", "disabled": true, "tags": {"env": "prod"}},
			{"id": "c4", "tags": {"env": "prod", "region": "us"}}
		],
		"include": [{"env": "prod"}],
		"exclude": [{"region": "us"}]
	}`
	// Same content with member names expressed via \u escapes (mixed
	// spellings, including a fully escaped include condition key).
	escaped := `{
		"app": "payments", "revision": "v1.2.3", "image": "reg/payments:v1.2.3",
		"batchSize": 2,
		"clusters": [
			{"id": "c3", "tags": {"env": "prod"}},
			{"id": "c1", "tags": {"env": "dev"}},
			{"id": "c2", "disabled": true, "tags": {"env": "prod"}},
			{"id": "c4", "tags": {"env": "prod", "region": "us"}}
		],
		"include": [{"env": "prod"}],
		"exclude": [{"region": "us"}]
	}`
	in1, err := ParseReleaseInput([]byte(direct))
	if err != nil {
		t.Fatalf("direct config: %v", err)
	}
	in2, err := ParseReleaseInput([]byte(escaped))
	if err != nil {
		t.Fatalf("escaped config: %v", err)
	}
	plan1, err := MakeReleasePlan(in1)
	if err != nil {
		t.Fatalf("direct plan: %v", err)
	}
	plan2, err := MakeReleasePlan(in2)
	if err != nil {
		t.Fatalf("escaped plan: %v", err)
	}
	if plan1.App != plan2.App {
		t.Fatalf("app info differs: %+v vs %+v", plan1.App, plan2.App)
	}
	if len(plan1.Batches) != len(plan2.Batches) {
		t.Fatalf("batch count differs: %+v vs %+v", plan1.Batches, plan2.Batches)
	}
	for i := range plan1.Batches {
		if plan1.Batches[i].Index != plan2.Batches[i].Index ||
			strings.Join(plan1.Batches[i].Clusters, ",") != strings.Join(plan2.Batches[i].Clusters, ",") {
			t.Fatalf("batch %d differs: %+v vs %+v", i, plan1.Batches[i], plan2.Batches[i])
		}
	}
	if len(plan1.Excluded) != len(plan2.Excluded) {
		t.Fatalf("excluded count differs: %+v vs %+v", plan1.Excluded, plan2.Excluded)
	}
	for i := range plan1.Excluded {
		if plan1.Excluded[i] != plan2.Excluded[i] {
			t.Fatalf("excluded[%d] differs: %+v vs %+v", i, plan1.Excluded[i], plan2.Excluded[i])
		}
	}

	// Escaped spelling of the optional spreadBy key behaves identically too.
	withSpreadDirect := `{` + escapedDupBase + `,"spreadBy":"zone","clusters":[` +
		`{"id":"a","tags":{"zone":"z1"}},{"id":"b","tags":{"zone":"z1"}},` +
		`{"id":"c","tags":{"zone":"z2"}}]}`
	withSpreadEscaped := `{` + escapedDupBase + `,"spreadBy":"zone","clusters":[` +
		`{"id":"a","tags":{"zone":"z1"}},{"id":"b","tags":{"zone":"z1"}},` +
		`{"id":"c","tags":{"zone":"z2"}}]}`
	p1, err := planFromDoc(t, withSpreadDirect)
	if err != nil {
		t.Fatalf("direct spreadBy: %v", err)
	}
	p2, err := planFromDoc(t, withSpreadEscaped)
	if err != nil {
		t.Fatalf("escaped spreadBy: %v", err)
	}
	if len(p1.Batches) != len(p2.Batches) {
		t.Fatalf("spread batch count differs: %+v vs %+v", p1.Batches, p2.Batches)
	}
	for i := range p1.Batches {
		if strings.Join(p1.Batches[i].Clusters, ",") != strings.Join(p2.Batches[i].Clusters, ",") {
			t.Fatalf("spread batch %d differs: %+v vs %+v", i, p1.Batches[i], p2.Batches[i])
		}
	}
}

// planFromDoc parses and plans a document, failing on either error.
func planFromDoc(t *testing.T, doc string) (ReleasePlan, error) {
	t.Helper()
	in, err := ParseReleaseInput([]byte(doc))
	if err != nil {
		return ReleasePlan{}, err
	}
	return MakeReleasePlan(in)
}

// TestPlanCLI_EscapedDuplicateMemberFailsCleanly is the command-level
// guarantee: reading such a file via "plan" exits non-zero, explains the
// decoded duplicate and its position on stderr, and writes no partial plan to
// stdout.
func TestPlanCLI_EscapedDuplicateMemberFailsCleanly(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "plan.json")
	doc := `{
		"app": "payments", "revision": "v1.2.3", "image": "reg/payments:v1.2.3",
		"batchSize": 2,
		"clusters": [
			{"id": "c1", "tags": {"env": "prod", "env": "dev"}},
			{"id": "c2"}
		]
	}`
	if err := os.WriteFile(path, []byte(doc), 0o644); err != nil {
		t.Fatal(err)
	}
	cmd := exec.Command("go", "run", "./cmd/darksafe", "plan", path)
	cmd.Dir = ".."
	var stdout, stderr strings.Builder
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	err := cmd.Run()
	if err == nil {
		t.Fatalf("expected non-zero exit; stdout=%q stderr=%q", stdout.String(), stderr.String())
	}
	if stdout.String() != "" {
		t.Fatalf("stdout must stay empty (no partial plan), got %q", stdout.String())
	}
	msg := stderr.String()
	if !strings.Contains(msg, `"env"`) {
		t.Fatalf("stderr should name decoded field, got %q", msg)
	}
	if !strings.Contains(msg, "$.clusters[0].tags") {
		t.Fatalf("stderr should name object position, got %q", msg)
	}
}

