// TestParse_EscapedSurrogatePairDuplicate covers a name with a legal
// supplementary-plane (non-BMP) character: written directly it must be the
// same name as a pair of UTF-16 surrogate escapes, in either order.
func TestParse_EscapedSurrogatePairDuplicate(t *testing.T) {
	// U+1F600 (😀): direct vs. "😀" surrogate pair.
	docs := []string{
		`{` + escapedDupBase + `,"clusters":[{"id":"x","tags":{"😀":1,"😀":2}}]}`,
		`{` + escapedDupBase + `,"clusters":[{"id":"x","tags":{"😀":1,"😀":2}}]}`,
		`{` + escapedDupBase + `,"clusters":[{"id":"x","tags":{"😀":1,"😀":2}}]}`,
	}
	for i, doc := range docs {
		err := parseDupErr(t, doc)
		msg := err.Error()
		if !strings.Contains(msg, "😀") {
			t.Fatalf("case %d: error should show decoded non-BMP name, got %q", i, msg)
		}
		if !strings.Contains(msg, "$.clusters[0].tags") {
			t.Fatalf("case %d: error should locate tags object, got %q", i, msg)
		}
