	}
	err = parseDupErr(t, `{`+escapedDupBase+`,"clusters":[],"meta":{"😀":1,"😀":2}}`)
	if !strings.Contains(err.Error(), "😀") || !strings.Contains(err.Error(), "$.meta") {
		t.Fatalf("unknown-field non-BMP duplicate not reported: %v", err)
	}
