// TestParse_EscapedNamesProduceEquivalentPlans checks that escaped and direct
// spellings of the same member names express identical content: app info,
// cluster selection, batch arrangement, and non-selection reasons must match
// between the two documents.
func TestParse_EscapedNamesProduceEquivalentPlans(t *testing.T) {
	direct := `{
		"app": "payments", "revision": "v1.2.3", "image": "reg/payments:v1.2.3",
		"batchSize": 2,
		"clusters": [
			{"id": "c3", "tags": {"env": "prod"}},
			{"id": "c1", "tags": {"env": "dev"}},
			{"id": "c2", "disabled": true, "tags": {"env": "prod"}},
			{"id": "c4", "tags": {"env": "prod", "region": "us"}}
		],
		"include": [{"env": "prod"}],
		"exclude": [{"region": "us"}]
	}`
	// Same content with member names expressed via \u escapes (mixed
	// spellings, including a fully escaped include condition key).
	escaped := `{
		"app": "payments", "revision": "v1.2.3", "image": "reg/payments:v1.2.3",
		"batchSize": 2,
		"clusters": [
			{"id": "c3", "tags": {"env": "prod"}},
			{"id": "c1", "tags": {"env": "dev"}},
			{"id": "c2", "disabled": true, "tags": {"env": "prod"}},
			{"id": "c4", "tags": {"env": "prod", "region": "us"}}
		],
		"include": [{"env": "prod"}],
		"exclude": [{"region": "us"}]
	}`
	in1, err := ParseReleaseInput([]byte(direct))
	if err != nil {
		t.Fatalf("direct config: %v", err)
	}
	in2, err := ParseReleaseInput([]byte(escaped))
	if err != nil {
		t.Fatalf("escaped config: %v", err)
	}
	plan1, err := MakeReleasePlan(in1)
	if err != nil {
		t.Fatalf("direct plan: %v", err)
	}
	plan2, err := MakeReleasePlan(in2)
	if err != nil {
		t.Fatalf("escaped plan: %v", err)
	}
	if plan1.App != plan2.App {
		t.Fatalf("app info differs: %+v vs %+v", plan1.App, plan2.App)
	}
	if len(plan1.Batches) != len(plan2.Batches) {
		t.Fatalf("batch count differs: %+v vs %+v", plan1.Batches, plan2.Batches)
	}
	for i := range plan1.Batches {
		if plan1.Batches[i].Index != plan2.Batches[i].Index ||
			strings.Join(plan1.Batches[i].Clusters, ",") != strings.Join(plan2.Batches[i].Clusters, ",") {
			t.Fatalf("batch %d differs: %+v vs %+v", i, plan1.Batches[i], plan2.Batches[i])
		}
	}
	if len(plan1.Excluded) != len(plan2.Excluded) {
		t.Fatalf("excluded count differs: %+v vs %+v", plan1.Excluded, plan2.Excluded)
	}
	for i := range plan1.Excluded {
		if plan1.Excluded[i] != plan2.Excluded[i] {
			t.Fatalf("excluded[%d] differs: %+v vs %+v", i, plan1.Excluded[i], plan2.Excluded[i])
		}
	}

	// Escaped spelling of the optional spreadBy key behaves identically too.
	withSpreadDirect := `{` + escapedDupBase + `,"spreadBy":"zone","clusters":[` +
		`{"id":"a","tags":{"zone":"z1"}},{"id":"b","tags":{"zone":"z1"}},` +
		`{"id":"c","tags":{"zone":"z2"}}]}`
	withSpreadEscaped := `{` + escapedDupBase + `,"spreadBy":"zone","clusters":[` +
		`{"id":"a","tags":{"zone":"z1"}},{"id":"b","tags":{"zone":"z1"}},` +
		`{"id":"c","tags":{"zone":"z2"}}]}`
	p1, err := planFromDoc(t, withSpreadDirect)
	if err != nil {
		t.Fatalf("direct spreadBy: %v", err)
	}
	p2, err := planFromDoc(t, withSpreadEscaped)
	if err != nil {
		t.Fatalf("escaped spreadBy: %v", err)
	}
	if len(p1.Batches) != len(p2.Batches) {
		t.Fatalf("spread batch count differs: %+v vs %+v", p1.Batches, p2.Batches)
	}
	for i := range p1.Batches {
		if strings.Join(p1.Batches[i].Clusters, ",") != strings.Join(p2.Batches[i].Clusters, ",") {
			t.Fatalf("spread batch %d differs: %+v vs %+v", i, p1.Batches[i], p2.Batches[i])
		}
	}
}

// planFromDoc parses and plans a document, failing on either error.
func planFromDoc(t *testing.T, doc string) (ReleasePlan, error) {
	t.Helper()
	in, err := ParseReleaseInput([]byte(doc))
	if err != nil {
		return ReleasePlan{}, err
	}
	return MakeReleasePlan(in)
}

// TestPlanCLI_EscapedDuplicateMemberFailsCleanly is the command-level
// guarantee: reading such a file via "plan" exits non-zero, explains the
// decoded duplicate and its position on stderr, and writes no partial plan to
// stdout.
func TestPlanCLI_EscapedDuplicateMemberFailsCleanly(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "plan.json")
	doc := `{
		"app": "payments", "revision": "v1.2.3", "image": "reg/payments:v1.2.3",
		"batchSize": 2,
		"clusters": [
			{"id": "c1", "tags": {"env": "prod", "env": "dev"}},
			{"id": "c2"}
		]
	}`
	if err := os.WriteFile(path, []byte(doc), 0o644); err != nil {
		t.Fatal(err)
	}
	cmd := exec.Command("go", "run", "./cmd/darksafe", "plan", path)
	cmd.Dir = ".."
	var stdout, stderr strings.Builder
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	err := cmd.Run()
	if err == nil {
		t.Fatalf("expected non-zero exit; stdout=%q stderr=%q", stdout.String(), stderr.String())
	}
	if stdout.String() != "" {
		t.Fatalf("stdout must stay empty (no partial plan), got %q", stdout.String())
	}
	msg := stderr.String()
	if !strings.Contains(msg, `"env"`) {
		t.Fatalf("stderr should name decoded field, got %q", msg)
	}
	if !strings.Contains(msg, "$.clusters[0].tags") {
		t.Fatalf("stderr should name object position, got %q", msg)
	}
}

