	// must behave identically to the direct spelling.
	withSpreadDirect := `{` + decodedDupBase + `,"spreadBy":"zone","clusters":[` +
		`{"id":"a","tags":{"zone":"z1"}},{"id":"b","tags":{"zone":"z1"}},` +
